    private static GRepData Decode(string base64)
    {
        byte[] data = Convert.FromBase64String(base64);
        return GRepParserV2.Parse(data, 0, (uint)(data.Length - 16))!;
    }

    [Fact]
    public void DecodedFaces_CarryTheirGInfoFlags()
    {
        var voidBody = Decode(VoidInstance6961482);
        Assert.Equal(6, voidBody.Faces.Count);
        Assert.All(voidBody.Faces, face => Assert.Equal(0x00088004u, face.GInfoFlags));

        var slab = Decode(Slab766598);
        Assert.NotEmpty(slab.Faces);
        Assert.All(slab.Faces, face => Assert.NotEqual(0u, face.GInfoFlags!.Value & 0x200u));
    }

    private static Element Box(int id, uint? flags)
    {
        double[][] corners = [[0, 0], [2, 0], [2, 1], [0, 1]];
        var faces = new List<GeoFace>
        {
            new() { Normal = [0, 0, -1], Origin = [0, 0, 0], OuterVertices = corners.AsEnumerable().Reverse().Select(p => new[] { p[0], p[1], 0.0 }).ToList(), GInfoFlags = flags },
            new() { Normal = [0, 0, 1], Origin = [0, 0, 1], OuterVertices = corners.Select(p => new[] { p[0], p[1], 1.0 }).ToList(), GInfoFlags = flags },
        };
        for (int i = 0; i < 4; i++)
        {
            var p = corners[i]; var q = corners[(i + 1) % 4];
            double sx = q[0] - p[0], sy = q[1] - p[1], length = Math.Sqrt(sx * sx + sy * sy);
            faces.Add(new GeoFace
            {
                Normal = [sy / length, -sx / length, 0], GInfoFlags = flags,
                OuterVertices = [[p[0], p[1], 0], [q[0], q[1], 0], [q[0], q[1], 1], [p[0], p[1], 1]],
            });
        }
        double[] box = [0, 0, 0, 2, 1, 1];
        return new Element
        {
            Id = id, TypeId = 102, Name = $"Generic {id}", CategoryId = -2000151, Category = "OST_GenericModel", References = [99],
            Geometry = new GeometryData { Faces = faces, BoundingBox = box, BrepSolids = [new GeoBrepSolid { FaceIndices = Enumerable.Range(0, 6).ToList(), IsClosed = true }] },
            BoundingBox = box, SerializedExportId = Guid.NewGuid(),
            Parameters = [new Parameter { Id = -1012100, StorageType = StorageType.Integer, Value = 99 }],
        };
    }

    private static string Export(IfcProfile version, Element element)
    {
        var info = new RevitFileInfo();
        info.Elements.Add(element);
        string path = Path.Combine(Path.GetTempPath(), $"revitreader-void-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter { Profile = version }.Export(info, path);
            return File.ReadAllText(path);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }
    }

    [Fact]
    public void HasOnlyUnfilledFaces_NeedsEveryFaceKnownAndWithoutTheFillBit()
    {
        Assert.True(IfcExporter.HasOnlyUnfilledFacesCurrent(Box(1, 0x00088004u)));
        Assert.False(IfcExporter.HasOnlyUnfilledFacesCurrent(Box(2, 0x00088204u)));
        // Faces whose flags are not known (placed from a nested symbol) count as filled; so does an element without faces.
        Assert.False(IfcExporter.HasOnlyUnfilledFacesCurrent(Box(3, null)));
        Assert.False(IfcExporter.HasOnlyUnfilledFacesCurrent(new Element { Id = 4 }));
        var mixed = Box(5, 0x00088004u);
        mixed.Geometry!.Faces![0].GInfoFlags = 0x00088204u;
        Assert.False(IfcExporter.HasOnlyUnfilledFacesCurrent(mixed));
    }

    [Fact]
    public void Current_WritesNoProxyForAnInstanceWithoutFilledFaces_ButTheFilledOneAndTheOlderTarget()
    {
        Assert.Contains("=IFCBUILDINGELEMENTPROXY(", Export(IfcProfile.Current, Box(1, 0x00088204u)));
        Assert.DoesNotContain("=IFCBUILDINGELEMENTPROXY(", Export(IfcProfile.Current, Box(1, 0x00088004u)));
        Assert.Contains("=IFCBUILDINGELEMENTPROXY(", Export(IfcProfile.Legacy, Box(1, 0x00088004u)));
    }
}
